	}
	defer removeFetchRef(repo)
	return ReadFromRef(ctx, repo, fetchRefName, SourceRemote)
}

func removeFetchRef(repo *git.Repository) {
	if err := repo.Storer.RemoveReference(fetchRefName); err != nil {
		return
	}
